    public sealed override List<Team> GetTactics()
    {
        List<Team> teams = [];

        // Main team
        Data.Seek((uint)_helper.TeamNameOffset);
        string name = Data.ReadString(Encoding.UTF8);
        teams.Add(LoadTeam(_helper.MainTeamInfoOffset, name, _helper.MainTeamPlayersOffset));

        // Custom Teams
        uint teamInfo = _helper.CustomTeamInfoOffset;
        string[] names = ["Team A", "Team B", "Team C"];
        uint teamPlayers = _helper.CustomTeamPlayersOffset;
        for (int i = 0; i < 3; i++)
        {
            teams.Add(LoadTeam(teamInfo, names[i], teamPlayers));
            teamInfo += 0x30;
            teamPlayers += 0x40;
        }

        return teams;
    }

    public override void SaveTactics(BinaryDataWriter writer)
    {
        if (!TeamsInitialized) return;

        // Chrono Storm Team
        SaveTeam(writer, Teams[0], _helper.MainTeamInfoOffset, _helper.MainTeamPlayersOffset, true);

        // Custom Teams
        uint teamInfo = _helper.CustomTeamInfoOffset;
        uint teamPlayers = _helper.CustomTeamPlayersOffset;
        for (int i = 0; i < 3; i++)
        {
            SaveTeam(writer, Teams[i + 1], teamInfo, teamPlayers);
            teamInfo += 0x30;
            teamPlayers += 0x40;
        }
    }

    private Team LoadTeam(uint teamInfo, string teamName, uint teamPlayers)
    {
        Data.Seek(teamInfo);

        IeGoHelper.Team team = Data.ReadStruct<IeGoHelper.Team>();
        Item? coach = Inventory.GetValueOrDefault(team.CoachIndex);
        Item? formation = Inventory.GetValueOrDefault(team.FormationIndex);
        Item? kit = Inventory.GetValueOrDefault(team.KitIndex);
        Item? emblem = Inventory.GetValueOrDefault(team.EmblemIndex);

        Data.Seek(teamPlayers);
        IeGoHelper.TeamPlayer teamPlayer = Data.ReadStruct<IeGoHelper.TeamPlayer>();
        List<Player?> players = teamPlayer.PlayersIndex.Where(x => x != 0x00).Select(x => Reserve.FirstOrDefault(y => y.Index == x)).ToList();
        List<int> playersFormationIndex = team.PlayersFormationIndex.Select(Convert.ToInt32).ToList();
        List<int> playersKitNumber = team.PlayerKitNumber.Select(Convert.ToInt32).ToList();

        return new Team(teamName, emblem, kit, formation, coach, players, playersFormationIndex, playersKitNumber);
    }

    private void SaveTeam(BinaryDataWriter writer, Team team, uint teamInfo, uint teamPlayers, bool teamNameCanEdit = false)
    {
        writer.Seek(teamInfo);
        writer.Write(team.Coach == null ? 0x00 : Inventory.FirstOrDefault(x => x.Value == team.Coach).Key);
        writer.Write(team.Formation == null ? 0x00 : Inventory.FirstOrDefault(x => x.Value == team.Formation).Key);
        writer.Write(team.Kit == null ? 0x00 : Inventory.FirstOrDefault(x => x.Value == team.Kit).Key);
        writer.Write(team.Emblem == null ? 0x00 : Inventory.FirstOrDefault(x => x.Value == team.Emblem).Key);
        writer.Write(team.PlayersFormationIndex.Select(x => (byte)x).ToArray());
        writer.Write(team.PlayersKitNumber.Select(x => (byte)x).ToArray());

        if (teamNameCanEdit)
        {
            writer.Seek((uint)_helper.TeamNameOffset);
            writer.Write(Encoding.UTF8.GetBytes(team.Name));
            writer.Write((byte)0x0);
            writer.Write((byte)0x88);
        }

        writer.Seek(teamPlayers);
        writer.Write(team.Players
            .Where(player =>
                {
                    if (player is not null) return true;
                    Console.Error.WriteLine("Player is null");
                    return false;
                }
            ).OfType<Player>()
            .SelectMany(x => BitConverter.GetBytes(x.Index)).ToArray());
    }

    public override void UpdateInventory()
    {
        // Find Equipment
        // TODO: Probably error prone
        Equipments = Inventory.Where(x => TCommon.Equipments.ContainsKey(x.Value.Id)).ToDictionary(x => x.Key, y => TCommon.Equipments[y.Value.Id]);
        Equipments.Add(0, TCommon.Equipments[0x0]);
    }
